    /// CR 120.10: Legacy `excess_only: bool` compatibility — a
    /// `DamageDealtThisTurn` serialized before the `channel: DamageChannel`
    /// migration must reload with the correct channel via the `excess_only`
    /// serde alias + compat deserializer, not silently default to `Total`.
    #[test]
    fn damage_channel_reads_legacy_excess_only_bool() {
        // Build the modern value (channel Total, elided) to get a valid
        // source/target JSON shape, then inject the legacy `excess_only` key.
        let modern_total = QuantityRef::DamageDealtThisTurn {
            source: Box::new(TargetFilter::Any),
            target: Box::new(TargetFilter::Any),
            aggregate: default_sum_aggregate(),
            group_by: None,
            damage_kind: default_damage_kind(),
            channel: DamageChannel::Total,
        };
        let mut v: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&modern_total).unwrap()).unwrap();
        v.as_object_mut()
            .unwrap()
            .insert("excess_only".to_string(), serde_json::Value::Bool(true));
        let back: QuantityRef = serde_json::from_value(v).unwrap();
        assert!(
            matches!(
                back,
                QuantityRef::DamageDealtThisTurn {
                    channel: DamageChannel::Excess,
                    ..
                }
            ),
            "legacy excess_only:true must map to DamageChannel::Excess, got {back:?}"
        );

        // `excess_only:false` maps to Total (the elided default).
        let mut v_false: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&modern_total).unwrap()).unwrap();
        v_false
            .as_object_mut()
            .unwrap()
            .insert("excess_only".to_string(), serde_json::Value::Bool(false));
        assert!(matches!(
            serde_json::from_value::<QuantityRef>(v_false).unwrap(),
            QuantityRef::DamageDealtThisTurn {
                channel: DamageChannel::Total,
                ..
            }
        ));

        // Modern representation still round-trips.
        let modern_excess = QuantityRef::DamageDealtThisTurn {
            source: Box::new(TargetFilter::Any),
            target: Box::new(TargetFilter::Any),
            aggregate: default_sum_aggregate(),
            group_by: None,
            damage_kind: default_damage_kind(),
            channel: DamageChannel::Excess,
        };
        let json = serde_json::to_string(&modern_excess).unwrap();
        assert_eq!(
            serde_json::from_str::<QuantityRef>(&json).unwrap(),
            modern_excess
        );
    }

    /// CR 608.2n: Legacy `exile_instead_of_graveyard_on_resolve: bool`
    /// compatibility — an `ExileWithAltCost` permission serialized before the
    /// `graveyard_replacement` migration must reload `true` as `Some(Exile)` via
    /// the serde alias + compat deserializer, not lose its exile-on-resolution
    /// rider.
    #[test]
    fn exile_with_alt_cost_reads_legacy_exile_on_resolve_bool() {
        let modern = CastingPermission::ExileWithAltCost {
            source_id: None,
            cost_provenance: crate::types::ability::ExileGrantCostProvenance::Alternative,
            cost: ManaCost::zero(),
            cast_transformed: false,
            constraint: None,
            granted_to: None,
            resolution_cleanup: None,
            duration: None,
            graveyard_replacement: None,
            enters_with_counter: None,
            enters_with_modifications: Default::default(),
            mana_spend_permission: None,
            cast_cost_modifier: None,
        };
        let mut v: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&modern).unwrap()).unwrap();
        v.as_object_mut().unwrap().insert(
            "exile_instead_of_graveyard_on_resolve".to_string(),
            serde_json::Value::Bool(true),
        );
        let back: CastingPermission = serde_json::from_value(v).unwrap();
        assert!(
            matches!(
                back,
                CastingPermission::ExileWithAltCost {
                    graveyard_replacement: Some(SpellStackToGraveyardReplacement::Exile),
                    ..
                }
            ),
            "legacy exile_instead_of_graveyard_on_resolve:true must map to Some(Exile), got {back:?}"
        );

        // `false` reloads as `None` (no rider), matching the pre-migration bool.
        let mut v_false: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&modern).unwrap()).unwrap();
        v_false.as_object_mut().unwrap().insert(
            "exile_instead_of_graveyard_on_resolve".to_string(),
            serde_json::Value::Bool(false),
        );
        assert!(matches!(
            serde_json::from_value::<CastingPermission>(v_false).unwrap(),
            CastingPermission::ExileWithAltCost {
                graveyard_replacement: None,
                ..
            }
        ));
    }

    #[test]
    fn play_from_exile_mode_serde_defaults_to_play_and_serializes_cast() {
        let legacy = serde_json::json!({
            "type": "PlayFromExile",
            "duration": "UntilEndOfTurn",
            "granted_to": 0,
        });
        let permission: CastingPermission = serde_json::from_value(legacy.clone())
            .expect("legacy play-from-exile permission deserializes");
        assert!(matches!(
            permission,
            CastingPermission::PlayFromExile {
                mode: CardPlayMode::Play,
                ..
            }
        ));
        assert!(
            !serde_json::to_value(&permission)
                .expect("serialize legacy-default permission")
                .as_object()
                .expect("permission is an object")
                .contains_key("mode"),
            "Play is the field-specific wire default and stays omitted"
        );

        let mut explicit_cast = legacy;
        explicit_cast["mode"] = serde_json::json!("Cast");
        let permission: CastingPermission =
            serde_json::from_value(explicit_cast).expect("explicit cast permission deserializes");
        assert!(matches!(
            permission,
            CastingPermission::PlayFromExile {
                mode: CardPlayMode::Cast,
                ..
            }
        ));
        assert_eq!(
            serde_json::to_value(permission).expect("serialize explicit cast permission")["mode"],
            serde_json::json!("Cast"),
            "Cast must remain explicit because it narrows a legacy PlayFromExile grant"
        );
    }

    /// CR 106.1 + CR 202.2c: the dynamic-color `AnyCombinationOfObjectColors`
    /// mana production round-trips through the custom `ManaProduction` (de)serializer.
    #[test]
    fn any_combination_of_object_colors_serde_roundtrip() {
        let mp = ManaProduction::AnyCombinationOfObjectColors {
            count: QuantityExpr::Fixed { value: 3 },
            scope: ObjectScope::Target,
        };
        let json = serde_json::to_string(&mp).unwrap();
        let back: ManaProduction = serde_json::from_str(&json).unwrap();
        assert_eq!(mp, back);

        // count defaults to one when omitted (default_quantity_one).
        let defaulted: ManaProduction = serde_json::from_str(
            r#"{"type":"AnyCombinationOfObjectColors","scope":{"type":"Target"}}"#,
        )
        .unwrap();
        assert_eq!(
            defaulted,
            ManaProduction::AnyCombinationOfObjectColors {
                count: default_quantity_one(),
                scope: ObjectScope::Target,
            }
        );
    }

    #[test]
    fn extra_turn_quantity_serde_is_backward_compatible() {
        let legacy: Effect = serde_json::from_str(r#"{"type":"ExtraTurn"}"#).unwrap();
        assert!(matches!(
            &legacy,
            Effect::ExtraTurn {
                target: TargetFilter::Controller,
                count: QuantityExpr::Fixed { value: 1 },
            }
        ));
        let legacy_json = serde_json::to_value(&legacy).unwrap();
        assert!(legacy_json.get("count").is_none());

        let two = Effect::ExtraTurn {
            target: TargetFilter::Player,
            count: QuantityExpr::Fixed { value: 2 },
        };
        let json = serde_json::to_value(&two).unwrap();
        assert_eq!(json["count"]["value"], serde_json::json!(2));
        assert_eq!(serde_json::from_value::<Effect>(json).unwrap(), two);

        let dynamic = Effect::ExtraTurn {
            target: TargetFilter::Controller,
            count: QuantityExpr::Ref {
                qty: QuantityRef::Variable { name: "X".into() },
            },
        };
        let dynamic_json = serde_json::to_value(&dynamic).unwrap();
        assert!(dynamic_json.get("count").is_some());
        assert_eq!(
            serde_json::from_value::<Effect>(dynamic_json).unwrap(),
            dynamic
        );
    }

    #[test]
    fn extra_turn_quantity_is_reached_by_all_generic_authorities() {
        let mut effect = Effect::ExtraTurn {
            target: TargetFilter::Controller,
            count: QuantityExpr::Ref {
                qty: QuantityRef::Variable { name: "X".into() },
            },
        };
        let dynamic = effect.count_expr().cloned().unwrap();
        let mut visited = Vec::new();
        effect.for_each_quantity_expr(&mut |quantity| visited.push(quantity.clone()));
        assert_eq!(visited, vec![dynamic]);

        *effect.count_expr_mut().unwrap() = QuantityExpr::Fixed { value: 2 };
        assert_eq!(effect.count_expr(), Some(&QuantityExpr::Fixed { value: 2 }));
        visited.clear();
        effect.for_each_quantity_expr(&mut |quantity| visited.push(quantity.clone()));
        assert_eq!(visited, vec![QuantityExpr::Fixed { value: 2 }]);
    }

    fn red_card_filter() -> TargetFilter {
        TargetFilter::Typed(TypedFilter::card().properties(vec![FilterProp::HasColor {
            color: ManaColor::Red,
        }]))
    }

    fn variable_x() -> QuantityExpr {
        QuantityExpr::Ref {
            qty: QuantityRef::Variable { name: "X".into() },
        }
    }

    /// Legacy card data serialized `AbilityCost::Reveal.count` as a bare
    /// integer; it still loads as `Fixed`, and a symbolic X count round-trips.
    #[test]
    fn reveal_cost_count_accepts_legacy_bare_integer() {
        let legacy: AbilityCost = serde_json::from_str(r#"{"type":"Reveal","count":1}"#).unwrap();
        assert_eq!(
            legacy,
            AbilityCost::Reveal {
                count: QuantityExpr::Fixed { value: 1 },
                filter: None,
                shared_quality: None,
            }
        );
        let missing: AbilityCost = serde_json::from_str(r#"{"type":"Reveal"}"#).unwrap();
        assert_eq!(missing, legacy, "a missing count defaults to one card");

        let symbolic = AbilityCost::Reveal {
            count: variable_x(),
            filter: Some(red_card_filter()),
            shared_quality: None,
        };
        let json = serde_json::to_string(&symbolic).unwrap();
        assert_eq!(
            serde_json::from_str::<AbilityCost>(&json).unwrap(),
            symbolic
        );
    }

    /// CR 107.3a: a reveal count is a cost quantity, so the cost-quantity walk
    /// visits (and can rewrite) it like a discard count.
    #[test]
    fn reveal_cost_count_is_visited_by_quantity_walk() {
        let reveal = AbilityCost::Reveal {
            count: variable_x(),
            filter: Some(red_card_filter()),
            shared_quality: None,
        };
        let mut visited = Vec::new();
        reveal.for_each_quantity_expr(&mut |quantity| visited.push(quantity.clone()));
        assert_eq!(visited, vec![variable_x()]);

        let mut composite = AbilityCost::Composite {
            costs: vec![
                AbilityCost::Mana {
                    cost: ManaCost::generic(1),
                },
                reveal.clone(),
                AbilityCost::Sacrifice(SacrificeCost::count(TargetFilter::SelfRef, 1)),
            ],
        };
        visited.clear();
        composite.for_each_quantity_expr(&mut |quantity| visited.push(quantity.clone()));
        assert_eq!(visited, vec![variable_x()]);

        composite.for_each_quantity_expr_mut(&mut |quantity| {
            *quantity = QuantityExpr::Fixed { value: 3 };
        });
        let AbilityCost::Composite { costs } = &composite else {
            unreachable!("the composite keeps its shape");
        };
        assert_eq!(
            costs[1],
            AbilityCost::Reveal {
                count: QuantityExpr::Fixed { value: 3 },
                filter: Some(red_card_filter()),
                shared_quality: None,
            }
        );

        // Positive control: the sibling discard count is visited too.
        let discard = AbilityCost::Discard {
            count: variable_x(),
            filter: None,
            selection: CardSelectionMode::Chosen,
            self_scope: DiscardSelfScope::FromHand,
        };
        visited.clear();
        discard.for_each_quantity_expr(&mut |quantity| visited.push(quantity.clone()));
        assert_eq!(visited, vec![variable_x()]);
    }

